async def act(page):
    # We're already on the shipping address edit page. Ensure UI is stable.
    await page.wait_for_load_state("networkidle")

    async def count(loc):
        return await loc.count()

    # Scope to the primary table that holds the address fields
    table = page.get_by_role("table").nth(0)

    # 1) Street Address: ensure first line = "321 Birch Boulevard", second line = "Suite 200"
    street_row = table.get_by_role("row", name="Street Address * 321 Birch Boulevard Suite 200")
    if await count(street_row) > 0:
        street_tbs = street_row.get_by_role("textbox")
        if await count(street_tbs) >= 1:
            await street_tbs.nth(0).fill("321 Birch Boulevard")
        if await count(street_tbs) >= 2:
            await street_tbs.nth(1).fill("Suite 200")
    else:
        # Fallback: try labeled textbox(s)
        global_street = page.get_by_role("textbox", name="Street Address *")
        if await count(global_street) > 0:
            await global_street.nth(0).fill("321 Birch Boulevard")
            if await count(global_street) > 1:
                await global_street.nth(1).fill("Suite 200")
        else:
            # Last resort: fill the first two textboxes on the page
            all_tbs = page.get_by_role("textbox")
            if await count(all_tbs) >= 1:
                await all_tbs.nth(0).fill("321 Birch Boulevard")
            if await count(all_tbs) >= 2:
                await all_tbs.nth(1).fill("Suite 200")

    # 2) City -> Dallas
    city_row = table.get_by_role("row", name="City * Miami Beach")
    if await count(city_row) > 0:
        city_tb = city_row.get_by_role("textbox", name="City *")
        if await count(city_tb) > 0:
            await city_tb.nth(0).fill("Dallas")
        else:
            any_city = city_row.get_by_role("textbox")
            if await count(any_city) > 0:
                await any_city.nth(0).fill("Dallas")
    else:
        global_city = page.get_by_role("textbox", name="City *")
        if await count(global_city) > 0:
            await global_city.nth(0).fill("Dallas")

    # 3) State/Province -> Texas (prefer combobox.select_option)
    state_row = table.get_by_role("row", name="State/Province * Florida")
    if await count(state_row) > 0:
        state_cb = state_row.get_by_role("combobox").nth(0)
        if await count(state_cb) > 0:
            # select by visible label; option "Texas" exists in the list
            await state_cb.select_option(label="Texas")
    else:
        global_state_cb = page.get_by_role("combobox", name="State/Province *")
        if await count(global_state_cb) > 0:
            await global_state_cb.nth(0).select_option(label="Texas")

    # 4) Zip/Postal Code -> 75201
    zip_row = table.get_by_role("row", name="Zip/Postal Code * 33139")
    if await count(zip_row) > 0:
        zip_tb = zip_row.get_by_role("textbox", name="Zip/Postal Code *")
        if await count(zip_tb) > 0:
            await zip_tb.nth(0).fill("75201")
        else:
            any_zip = zip_row.get_by_role("textbox")
            if await count(any_zip) > 0:
                await any_zip.nth(0).fill("75201")
    else:
        global_zip = page.get_by_role("textbox", name="Zip/Postal Code *")
        if await count(global_zip) > 0:
            await global_zip.nth(0).fill("75201")

    # 5) Click the Save button to persist changes. This is expected to submit and navigate away.
    save_btn = page.get_by_role("button", name="Save Order Address")
    if await count(save_btn) > 0:
        await save_btn.nth(0).click()
        return

    # Fallback generic Save
    generic_save = page.get_by_role("button", name="Save")
    if await count(generic_save) > 0:
        await generic_save.nth(0).click()
        return

    # If no save button found, end without clicking.
    return

